head.script:
// displayFormatter 호출 인자 기록 (Column 별)
scwin.calls = { "p_sel" : [], "p_auto" : [] };

scwin.onpageload = function () {
    let arr = [
        { "raw" : "A", "p_sel" : "A", "p_auto_none" : "A", "p_auto" : "A" },
        { "raw" : "B", "p_sel" : "B", "p_auto_none" : "B", "p_auto" : "B" },
        { "raw" : "C", "p_sel" : "C", "p_auto_none" : "C", "p_auto" : "C" }
    ];
    dlt_a.setJSON(arr);
};

// displayFormatter : 값을 대괄호로 감싸 반환 (select Column 용)
scwin.fmt_bracket_sel = function (data) {
    scwin.calls.p_sel.push(String(data));
    if (data === "" || data === null || typeof data === "undefined") {
        return data;
    }
    return "[" + data + "]";
};

// displayFormatter : 값을 대괄호로 감싸 반환 (autoComplete Column 용)
scwin.fmt_bracket_auto = function (data) {
    scwin.calls.p_auto.push(String(data));
    if (data === "" || data === null || typeof data === "undefined") {
        return data;
    }
    return "[" + data + "]";
};

// 각 Column Row 0 의 화면 표시값과 displayFormatter 호출 여부 출력
scwin.btn_check_onclick = function (e) {
    let cols = [
        ["select + displayFormatter", "p_sel", "p_sel"],
        ["autoComplete (displayFormatter 미설정)", "p_auto_none", ""],
        ["autoComplete + displayFormatter", "p_auto", "p_auto"]
    ];
    for (let i = 0; i < cols.length; i++) {
        let text = cols[i][0] + " : " + scwin.getCellText(0, cols[i][1]);
        if (cols[i][2] !== "") {
            let c = scwin.calls[cols[i][2]];
            text += " / displayFormatter 호출 : " + (c.length === 0 ? "없음" : c.length + "회 (" + c.slice(0, 3).join(", ") + ")");
        }
        scwin.setReturnValue(text);
    }
};

// 화면에 표시된 셀 텍스트
scwin.getCellText = function (rowIndex, colId) {
    let el = document.getElementById(grd_a.id + "_cell_" + rowIndex + "_" + grd_a.getColumnIndex(colId));
    return el ? el.innerText.replace(/\n/g, " ").trim() : "(셀 없음)";
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
